#include <fmt/format.h>
#include <cstring>
#include <vector>
#include <iostream>

// Test various format strings ending with multi-byte chars at the last byte
void test(const std::vector<char>& fmtbuf) {
  fmt::string_view fmtstr(fmtbuf.data(), fmtbuf.size());
  try {
    fmt::memory_buffer out;
    fmt::format_to(out, fmtstr, fmt::arg("x", 42));
    std::cout << "ok\n";
  } catch (std::exception& e) {
    std::cout << "exception: " << e.what() << "\n";
  }
}

int main() {
  // Case: format string ends with a multi-byte char at the last byte
  // "{:\xE0\x80\x80" - fill char is 3-byte UTF-8, no align char, no closing brace
  std::vector<char> f1 = {'{', ':', (char)0xE0, (char)0x80, (char)0x80};
  test(f1);
  // "{:\xE0\x80\x80>" - fill char 3-byte, then '>'
  std::vector<char> f2 = {'{', ':', (char)0xE0, (char)0x80, (char)0x80, '>'};
  test(f2);
  // "{:\xE0\x80\x80\x80" - 4-byte fill char at end
  std::vector<char> f3 = {'{', ':', (char)0xE0, (char)0x80, (char)0x80, (char)0x80};
  test(f3);
  // "{:\xE0\x80\x80\x80\x80" - 5-byte fill char at end
  std::vector<char> f4 = {'{', ':', (char)0xE0, (char)0x80, (char)0x80, (char)0x80, (char)0x80};
  test(f4);
  return 0;
}
